                i += 1;
            },
            'T' => {
                try result.appendSlice(alloc, ctx.pane_title);
                i += 1;
            },
            'H' => {
                try result.appendSlice(alloc, ctx.host);
                i += 1;
            },
            '{' => {
                // Long form: #{variable_name}, #{?var,true,false}, #{==:a,b}, #{l:str}
