            '[' => {
                // Style: #[fg=red] — pass through for style processing
                try result.append(alloc, '#');
                try result.append(alloc, '[');
                i += 1;
            },
            else => {
                try result.append(alloc, '#');
                try result.append(alloc, fmt[i]);
                i += 1;
            },
