224	fn appendTimeFormatSegment(alloc: std.mem.Allocator, result: *std.ArrayListAligned(u8, null), fmt_segment: []const u8) !void {
225	    if (fmt_segment.len == 0) return;
226	
227	    const fmt_z = try alloc.dupeZ(u8, fmt_segment);
228	    defer alloc.free(fmt_z);
229	
230	    var now: i64 = 0;
231	    _ = time(&now);
232	    const tm = localtime(&now) orelse {
233	        try result.appendSlice(alloc, fmt_segment);
234	        return;
235	    };
236	
237	    var buf: [128]u8 = undefined;
238	    const written = strftime(&buf, buf.len, fmt_z, tm);
239	    if (written == 0) {
240	        try result.appendSlice(alloc, fmt_segment);
241	        return;
242	    }
243	    try result.appendSlice(alloc, buf[0..written]);
244	}
