 26	    /// Render the status bar for a given width.
 27	    pub fn render(self: *const StatusBar, alloc: std.mem.Allocator, cols: u32, ctx: *const format.FormatContext) ![]u8 {
 28	        if (!self.enabled or cols == 0) {
 29	            return try alloc.alloc(u8, 0);
 30	        }
 31	
 32	        const left = try format.expand(alloc, self.left, ctx);
 33	        defer alloc.free(left);
 34	        const right = try format.expand(alloc, self.right, ctx);
 35	        defer alloc.free(right);
 36	
 37	        return self.renderSections(alloc, cols, left, "", right);
 38	    }
 39	
 40	    /// Render the status bar with explicit left/window-list/right sections.
 41	    pub fn renderSections(
 42	        self: *const StatusBar,
 43	        alloc: std.mem.Allocator,
 44	        cols: u32,
 45	        left: []const u8,
 46	        center: []const u8,
 47	        right: []const u8,
 48	    ) ![]u8 {
 49	        if (!self.enabled or cols == 0) {
 50	            return try alloc.alloc(u8, 0);
 51	        }
 52	
 53	        var leading: std.ArrayListAligned(u8, null) = .empty;
 54	        defer leading.deinit(alloc);
 55	
 56	        if (left.len > 0) {
 57	            try leading.appendSlice(alloc, left);
 58	        }
 59	        if (center.len > 0) {
 60	            if (leading.items.len > 0) {
 61	                try leading.append(alloc, ' ');
 62	            }
 63	            try leading.appendSlice(alloc, center);
 64	        }
 65	
 66	        var line: std.ArrayListAligned(u8, null) = .empty;
 67	        errdefer line.deinit(alloc);
 68	
 69	        const right_len = @min(right.len, cols);
 70	        const leading_budget = cols - right_len;
 71	        const leading_len = @min(leading.items.len, leading_budget);
 72	        try line.appendSlice(alloc, leading.items[0..leading_len]);
 73	
 74	        while (line.items.len < leading_budget) {
 75	            try line.append(alloc, ' ');
 76	        }
 77	
 78	        try line.appendSlice(alloc, right[0..right_len]);
 79	
 80	        return try line.toOwnedSlice(alloc);
 81	    }
 82	};
